//! 🧪️ Portable octet cases keep exact backing and refused prefixes under original recipients.
use super::*;
use semio_framework_value::native_encoding::{NativeEncodeConstructionRecipient,NativeEncodeWorkRecipient};
struct Work{remaining:u64,actual:u64}
impl NativeEncodeWorkRecipient for Work{fn admits(&mut self,_:u64,additional:u64)->Result<bool,ValueError>{Ok(additional<=self.remaining)}fn committed(&mut self,actual:u64)->Result<(),ValueError>{self.remaining-=actual;self.actual+=actual;Ok(())}}
struct Recipient{grant:RetainedCloneGrant,submitted:RetainedCloneProgress,refuse_copy:bool,quoted:Option<RetainedCloneGrant>}
impl NativeEncodeConstructionRecipient for Recipient{
 fn submitted(&self)->RetainedCloneProgress{self.submitted}
 fn grant(&mut self,_:semio_framework_value::RetirementDemand)->Result<RetainedCloneGrant,ValueError>{self.quoted=Some(self.grant);Ok(self.grant)}
 fn accept(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{assert_eq!(Some(grant),self.quoted.take());self.submitted=self.submitted.checked_add(progress)?;if self.refuse_copy&&progress.retained_capacity_bytes==0{Err(ValueError::literal(ValueRefusalKind::Canceled,"original blob receipt refused"))}else{Ok(())}}
}
#[test]
fn encoded_octets_keep_original_backing_prefix_and_receipt(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let count=fixture["payloadBytes"].as_u64().unwrap()as usize;let pattern=fixture["pattern"].as_array().unwrap();let input:Vec<u8>=(0..count).map(|i|pattern[i%pattern.len()].as_u64().unwrap()as u8).collect();
 for case in fixture["cases"].as_array().unwrap(){
  let grant=RetainedCloneGrant{maximum_items:8,maximum_copy_bytes:count+size_of::<Vec<u8>>(),maximum_capacity_bytes:count,maximum_release_bytes:count,maximum_depth:4};
  let mut recipient=Recipient{grant,submitted:Default::default(),refuse_copy:case["name"]=="first-copy-receipt",quoted:None};let mut work=Work{remaining:if case["name"]=="before-allocation"{0}else{8},actual:0};
  let mut callback=|_|true;let mut native=NativeEncodeControl::new(count,&mut callback);let mut body=NativeSnapshotBodyWallet::new(grant);let mut output=Vec::new();let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation_state=crate::NativeSnapshotEncodeAllocation::default();
  let mut construction_issuer=semio_framework_value::native_encoding::NativeEncodeConstructionIssuer::new();let mut work_issuer=semio_framework_value::native_encoding::NativeEncodeWorkIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let mut work_loan=work_issuer.loan(&mut work);let result=native.with_construction_recipient(&mut construction_loan,|native|native.with_work_recipient(&mut work_loan,|native|Ok::<_,ValueError>(body.copy_bytes_encoded(native,&input,&mut output,&mut marker,&mut unwind,&mut allocation_state,1)))).unwrap();
  assert_eq!(result.result.is_err(),case["refused"].as_bool().unwrap());assert_eq!(output.len(),case["retained"].as_u64().unwrap()as usize);assert_eq!(output,&input[..output.len()]);assert_eq!(native.actual_work(),case["work"].as_u64().unwrap());assert_eq!(result.work,native.actual_work());if work.actual==0{assert_eq!(native.owned_bytes(),0);}assert_eq!(work.actual,native.actual_work());assert_eq!(recipient.submitted,body.progress());assert!(unwind.is_none());
  assert_eq!(output.capacity(),if native.actual_work()==0{0}else{count});assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::from_slice::<serde_json::Value>(&serde_json::to_vec(&input[..output.len()]).unwrap()).unwrap());
  let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:256};
  close(output,close_grant);close(allocation_state,close_grant);if let Err(failure)=result.result{close(failure,close_grant);}
 }
}

fn close<T:semio_framework_value::retirement::RetireOwned>(value:T,grant:RetainedCloneGrant){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(value).ok().unwrap();for _ in 0..4096{if owner.terminal_is_empty(){break}let turn=owner.step(grant);turn.unwrap();}assert!(owner.terminal_is_empty());}

#[test]
fn refused_exact_backing_records_performed_zero_in_original_allocation(){
 let bytes=4*size_of::<u64>();let grant=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:128,maximum_capacity_bytes:bytes,maximum_release_bytes:bytes,maximum_depth:4};let mut recipient=Recipient{grant,submitted:Default::default(),refuse_copy:false,quoted:None};let mut work=Work{remaining:4,actual:0};let mut callback=|_|true;let mut native=NativeEncodeControl::new(bytes,&mut callback);let mut output=None;let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=crate::NativeSnapshotEncodeAllocation::default();let mut construction_issuer=semio_framework_value::native_encoding::NativeEncodeConstructionIssuer::new();let mut work_issuer=semio_framework_value::native_encoding::NativeEncodeWorkIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let mut work_loan=work_issuer.loan(&mut work);
 let((turn,refused),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_trace_memory_testing::refuse_one_allocation_on_this_thread(||native.with_construction_recipient(&mut construction_loan,|native|native.with_work_recipient(&mut work_loan,|native|{let mut owner=crate::NativeSnapshotEncodeOwner::new(native,grant);Ok::<_,ValueError>(owner.allocate_vector::<u64>(4,&mut output,&mut marker,&mut unwind,&mut allocation,1))})).unwrap()));drop(construction_loan);drop(work_loan);assert_eq!(refused,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(turn.work,1);assert!(output.is_none());let failure=turn.result.unwrap_err();let Some(crate::NativeSnapshotAllocationFailure::Encode(outcome))=failure.allocation() else{panic!("original allocation outcome missing")};assert_eq!(outcome.actual,Some(0));assert_eq!(allocation.actual,Some(0));assert_eq!(recipient.submitted.retained_capacity_bytes,0);assert_eq!(work.actual,1);assert!(unwind.is_none());let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(allocation,close_grant);close(failure,close_grant);
}

#[test]
fn refused_decode_backing_records_performed_zero_in_original_allocation(){
 use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeDecodeConstructionRecipient,NativeConstructionRecipientIssuer,OriginalWorkRecipient,OriginalWorkQuote,OriginalWorkQuoteComplete,OriginalWorkActionIssuer};
 struct DecodeWork{remaining:u64}impl OriginalWorkRecipient for DecodeWork{fn admits<'a>(&mut self,quote:OriginalWorkQuote<'a>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'a>{quote.complete(Ok(observed.checked_add(additional).is_some_and(|total|total<=self.remaining)))}}
 struct DecodeRecipient{grant:RetainedCloneGrant,submitted:RetainedCloneProgress}impl NativeDecodeConstructionRecipient for DecodeRecipient{fn submitted(&self)->RetainedCloneProgress{self.submitted}fn grant(&mut self,_:semio_framework_value::RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)}fn accept(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{assert_eq!(grant,self.grant);self.submitted=self.submitted.checked_add(progress)?;Ok(())}}
 let bytes=4*size_of::<u64>();let grant=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:128,maximum_capacity_bytes:bytes,maximum_release_bytes:bytes,maximum_depth:4};let mut recipient=DecodeRecipient{grant,submitted:Default::default()};let mut work=DecodeWork{remaining:4};let mut callback=|_|true;let mut native=NativeDecodeControl::new(bytes,&mut callback);let mut output=None;let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=crate::NativeSnapshotDecodeAllocation::default();let mut construction_issuer=NativeConstructionRecipientIssuer::new();let mut work_issuer=OriginalWorkActionIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let mut work_loan=work_issuer.loan(&mut work);
 let((turn,refused),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_trace_memory_testing::refuse_one_allocation_on_this_thread(||native.with_construction_recipient(&mut construction_loan,|native|native.with_work_recipient(&mut work_loan,|native|{let mut owner=crate::NativeSnapshotDecodeOwner::new(native,grant);Ok::<_,ValueError>(owner.allocate_vector::<u64>(4,&mut output,&mut marker,&mut unwind,&mut allocation,1))})).unwrap()));drop(construction_loan);drop(work_loan);assert_eq!(refused,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(turn.work,1);assert!(output.is_none());let failure=turn.result.unwrap_err();let Some(crate::NativeSnapshotAllocationFailure::Decode(outcome))=failure.allocation() else{panic!("original decode allocation outcome missing")};assert_eq!(outcome.actual,Some(0));assert_eq!(allocation.actual,Some(0));assert_eq!(recipient.submitted.retained_capacity_bytes,0);assert_eq!(native.actual_work(),1);assert!(unwind.is_none());let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(allocation,close_grant);close(failure,close_grant);
}

#[test]fn refused_octet_copy_records_performed_zero_before_any_output(){let input=[1u8,2,3,4];let grant=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:128,maximum_capacity_bytes:input.len(),maximum_release_bytes:input.len(),maximum_depth:4};let mut recipient=Recipient{grant,submitted:Default::default(),refuse_copy:false,quoted:None};let mut work=Work{remaining:4,actual:0};let mut callback=|_|true;let mut native=NativeEncodeControl::new(input.len(),&mut callback);let mut body=NativeSnapshotBodyWallet::new(grant);let mut output=Vec::new();let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=crate::NativeSnapshotEncodeAllocation::default();let mut construction_issuer=semio_framework_value::native_encoding::NativeEncodeConstructionIssuer::new();let mut work_issuer=semio_framework_value::native_encoding::NativeEncodeWorkIssuer::new();let mut construction_loan=construction_issuer.loan(&mut recipient);let mut work_loan=work_issuer.loan(&mut work);let((turn,refused),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_trace_memory_testing::refuse_one_allocation_on_this_thread(||native.with_construction_recipient(&mut construction_loan,|native|native.with_work_recipient(&mut work_loan,|native|Ok::<_,ValueError>(body.copy_bytes_encoded(native,&input,&mut output,&mut marker,&mut unwind,&mut allocation,1)))).unwrap()));drop(construction_loan);drop(work_loan);assert_eq!(refused,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(turn.work,1);assert!(output.is_empty()&&output.capacity()==0);let failure=turn.result.unwrap_err();let Some(crate::NativeSnapshotAllocationFailure::Encode(outcome))=failure.allocation() else{panic!("original octet allocation outcome missing")};assert_eq!(outcome.actual,Some(0));assert_eq!(allocation.actual,Some(0));assert_eq!(recipient.submitted.retained_capacity_bytes,0);assert_eq!(work.actual,1);assert!(unwind.is_none());let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(output,close_grant);close(allocation,close_grant);close(failure,close_grant);}
